import{_ as e,o as a,c as s,a2 as l}from"./chunks/framework.BXzK3EA4.js";const r="/img/%E7%BD%91%E7%BB%9C/tls-handshake/tls-full-flow.svg",c=JSON.parse('{"title":"HTTPS 握手完整流程","description":"协商版本与密码套件:客户端发 ClientHello,列出支持的 TLS 版本和 cipher suites,服务端选一个","frontmatter":{},"headers":[],"relativePath":"网络/12-tls-handshake.md","filePath":"网络/12-tls-handshake.md","lastUpdated":1793545253000}'),o={name:"网络/12-tls-handshake.md"};function i(n,t,T,h,d,g){return a(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="https-握手完整流程" tabindex="-1">HTTPS 握手完整流程 <a class="header-anchor" href="#https-握手完整流程" aria-label="Permalink to &quot;HTTPS 握手完整流程&quot;">​</a></h1><p><img src="'+r+'" alt="HTTPS 完整握手流程"></p><h3 id="关键点" tabindex="-1">关键点: <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点:&quot;">​</a></h3><ul><li><strong>非对称加密</strong>(RSA/ECDHE)用于交换密钥</li><li><strong>对称加密</strong>(AES)用于加密实际数据</li><li><strong>散列</strong>(SHA-256)用于完整性校验</li><li><strong>证书</strong>解决&quot;公钥信任&quot;问题:用 CA 私钥签名服务器公钥,客户端用 CA 公钥验证</li><li><strong>TLS 1.3</strong> 把 2-RTT 压到 1-RTT,且默认前向保密 — 上图右侧有对比说明</li></ul><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><h3 id="q1-https-握手做了哪几件事" tabindex="-1">Q1：HTTPS 握手做了哪几件事? <a class="header-anchor" href="#q1-https-握手做了哪几件事" aria-label="Permalink to &quot;Q1：HTTPS 握手做了哪几件事?&quot;">​</a></h3><ol><li><strong>协商版本与密码套件</strong>:客户端发 ClientHello,列出支持的 TLS 版本和 cipher suites,服务端选一个</li><li><strong>服务端身份认证</strong>:发证书,客户端验证证书链 + 域名 + 有效期</li><li><strong>协商会话密钥</strong>: <ul><li>TLS 1.2 及以前:ServerHello 里发 <code>ServerKeyExchange</code> 里的 ECDHE 参数 → 2-RTT</li><li>TLS 1.3:把证书签名和密钥交换<strong>合并</strong>进 ServerHello → <strong>1-RTT</strong></li></ul></li><li><strong>Finished 消息</strong>:校验握手过程没被篡改(握手 transcript 的摘要)</li></ol><p><strong>TLS 1.3 的改进</strong>:去掉了 RSA 密钥交换(无前向安全)、去掉了 CBC 模式、 去掉了压缩(CRIME 攻击)、0-RTT 会话恢复。</p><h3 id="q2-为什么-https-页面里的图片可以走-http-js-却不行" tabindex="-1">Q2：为什么 HTTPS 页面里的图片可以走 HTTP,JS 却不行? <a class="header-anchor" href="#q2-为什么-https-页面里的图片可以走-http-js-却不行" aria-label="Permalink to &quot;Q2：为什么 HTTPS 页面里的图片可以走 HTTP,JS 却不行?&quot;">​</a></h3><p>这是「主动内容 vs 被动内容」的区别:</p><ul><li><strong>主动内容</strong>(script / iframe / fetch / XHR):能执行代码或读取数据, 明文传输会泄漏页面数据,并让 HTTPS 的保证作废 → 浏览器<strong>直接拦截</strong></li><li><strong>被动内容</strong>(图片 / 音视频):只是显示,不能读页面数据 → 历史上只是警告, 现代浏览器也改为拦截并<strong>自动升级成 HTTPS 请求</strong></li></ul><p><strong>排查</strong>:DevTools → Security 面板,或 Console 里的 Mixed Content 警告。</p><h3 id="q3-tls-1-3-为什么把-2-rtt-压到-1-rtt" tabindex="-1">Q3：TLS 1.3 为什么把 2-RTT 压到 1-RTT? <a class="header-anchor" href="#q3-tls-1-3-为什么把-2-rtt-压到-1-rtt" aria-label="Permalink to &quot;Q3：TLS 1.3 为什么把 2-RTT 压到 1-RTT?&quot;">​</a></h3><p>TLS 1.2 的流程是:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ClientHello → ServerHello + Certificate + ServerKeyExchange → ClientKeyExchange + CCS + Finished → ...</span></span></code></pre></div><p>服务端要<strong>分两趟</strong>发:先发证书,再发密钥交换参数(因为客户端要先验证证书)。</p><p>TLS 1.3 做了两个改变:</p><ol><li><strong>把密钥交换参数和证书签名合并到 ServerHello 里</strong>,服务端一次发完</li><li><strong>客户端的 Finished 可以提前发</strong>(不阻塞服务端发自己的 Finished)</li></ol><p>结果:完整握手 1-RTT,会话恢复 0-RTT。</p><p><strong>代价</strong>:0-RTT 的数据可能被重放(early data),所以<strong>不能用于有副作用的请求</strong> (比如转账)。服务端要么拒绝 early data,要么做幂等处理。</p><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>TLS 握手四件事:协商版本套件、验证服务端身份、协商会话密钥、Finished 防篡改。</li><li>TLS 1.3 的关键改进是把密钥交换和证书签名合并进 ServerHello,把握手压到 1-RTT,并去掉了无前向安全的 RSA 交换。</li><li>混合内容(主动 vs 被动)现代浏览器一律拦截,被动内容会尝试自动升级成 HTTPS。</li><li>0-RTT 会带来重放风险,不能用于有副作用的请求,服务端要做幂等。</li></ul>',22)])])}const S=e(o,[["render",i]]);export{c as __pageData,S as default};
